"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass
from datetime import timedelta, timezone
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

SIZE = re.compile(r"([0-9]+)([KkMmGg]?)\Z")
DURATION = re.compile(r"([0-9]+)([mhd])\Z")
OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
COUNT = re.compile(r"[0-9]+\Z")
SECTION = re.compile(r"\[(.*)\]\Z")


@dataclass(frozen=True)
class Settings:
    max_size: int | None = None
    max_age: timedelta | None = None
    naming: str = "numbered"
    offset: timezone = timezone.utc
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


def _size(text):
    m = SIZE.match(text)
    if not m:
        raise ValueError(text)
    return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]


def _duration(text):
    m = DURATION.match(text)
    if not m:
        raise ValueError(text)
    unit = {"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]
    return timedelta(**{unit: int(m.group(1))})


def _offset(text):
    m = OFFSET.match(text)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise ValueError(text)
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return timezone(-delta if m.group(1) == "-" else delta)


def _count(minimum):
    def parse(text):
        if not COUNT.match(text) or int(text) < minimum:
            raise ValueError(text)
        return int(text)

    return parse


def _naming(text):
    if text not in ("numbered", "dated"):
        raise ValueError(text)
    return text


def _off_or(parser):
    def parse(text):
        return None if text == "off" else parser(text)

    return parse


PARSERS = {
    "max_size": _off_or(_size),
    "max_age": _off_or(_duration),
    "naming": _naming,
    "offset": _offset,
    "compress_after": _count(0),
    "keep": _count(1),
    "keep_days": _off_or(_count(1)),
}


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections

    def names(self) -> set:
        return set(self.sections)

    def settings(self, name: str) -> Settings:
        values = dict(self.defaults)
        values.update(self.sections.get(name, {}))
        return Settings(**values)


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"{path.name}: {e}") from None

    def bad(why):
        return DataError("policy", f"{path.name}: {why}")

    defaults, sections = {}, {}
    seen_defaults = False
    current = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        m = SECTION.match(line)
        if m:
            title = m.group(1)
            if title == "defaults":
                if seen_defaults:
                    raise bad("section defaults twice")
                seen_defaults = True
                current = defaults
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    raise bad(f"section {name} twice")
                current = sections[name] = {}
            else:
                raise bad(f"unknown section {title}")
            continue
        if current is None or "=" not in line:
            raise bad(f"bad line {line}")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key not in PARSERS:
            raise bad(f"unknown key {key}")
        if key in current:
            raise bad(f"key {key} twice")
        try:
            current[key] = PARSERS[key](value)
        except ValueError:
            raise bad(f"bad value for {key}") from None
    return Policy(defaults, sections)
