"""rotate (docs/rotate.md)."""

import gzip
import re
from dataclasses import dataclass
from datetime import date, timedelta

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

NUMBER = "[1-9][0-9]*"
DAY = r"[0-9]{4}-[0-9]{2}-[0-9]{2}"
COUNTER = "[2-9]|[1-9][0-9]+"


@dataclass
class Archive:
    key: tuple
    old: str | None
    time: object = None
    new: bool = False
    content: bytes | None = None
    name: str | None = None
    compress: bool = False


def _validate_state(doc, existing):
    def bad(why):
        return DataError("state", f"state.json: {why}")

    for name, entry in doc["streams"].items():
        if name not in existing:
            continue
        if "opened" in entry and dates.parse_iso(entry["opened"], legacy=True) is None:
            raise bad(f"{name}: bad opened")
        if "archives" in entry:
            archives = entry["archives"]
            if not isinstance(archives, dict):
                raise bad(f"{name}: archives is not an object")
            for value in archives.values():
                if dates.parse_iso(value, legacy=True) is None:
                    raise bad(f"{name}: bad archive time")
        if "rotations" in entry:
            value = entry["rotations"]
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise bad(f"{name}: bad rotations")


def _find_archives(logs, name, naming):
    if naming == "numbered":
        pattern = re.compile(rf"{re.escape(name)}\.log\.({NUMBER})(\.gz)?\Z")
    else:
        pattern = re.compile(rf"{re.escape(name)}\.log\.({DAY})(?:\.({COUNTER}))?(\.gz)?\Z")
    found = {}
    if not logs.is_dir():
        return []
    for path in logs.iterdir():
        m = pattern.match(path.name)
        if not m or not path.is_file():
            continue
        if naming == "numbered":
            key = (int(m.group(1)),)
        else:
            try:
                day = date.fromisoformat(m.group(1))
            except ValueError:
                continue
            key = (day, int(m.group(2) or 1))
        if key in found:
            raise DataError("archives", f"{name}: two archives in the same place")
        found[key] = Archive(key, path.name)
    if naming == "numbered":
        return [found[key] for key in sorted(found)]
    return [found[key] for key in sorted(found, reverse=True)]


def _first_time(path):
    with path.open("rb") as f:
        line = f.readline()
    text = line.decode("utf-8", errors="replace").rstrip("\n")
    head, sep, _ = text.partition(" ")
    return dates.parse_iso(head) if sep else None


def run(ctx, names, dry_run, force):
    pol = policy.load(ctx.policy_path)
    doc = ctx.state
    logs = streams.logs_dir(ctx.data)
    existing = set(streams.active(ctx.data)) | pol.names()
    _validate_state(doc, existing)
    names = sorted(set(names)) if names else sorted(existing)
    for name in names:
        if name not in existing:
            raise Refused("unknown-stream", f"no stream {name}")
    plans = []
    for name in names:
        settings = pol.settings(name)
        plans.append((name, settings, _find_archives(logs, name, settings.naming)))

    out, writes, removals = [], [], []
    rotated = removed = compressed = 0
    new_entries = {}
    for name, settings, archives in plans:
        entry = doc["streams"].get(name, {})
        times = {}
        for key, value in (entry.get("archives") or {}).items():
            times[key] = value
        log = streams.log_path(ctx.data, name)
        reason = None
        if not log.is_file():
            what = "no log"
        elif log.stat().st_size == 0:
            what = "empty"
        elif force:
            reason = "forced"
        elif settings.max_size is not None and log.stat().st_size >= settings.max_size:
            reason = "size"
        else:
            reason = None
            if settings.max_age is not None:
                opened = dates.parse_iso(entry["opened"], legacy=True) if "opened" in entry else _first_time(log)
                if opened is not None and ctx.now - opened >= settings.max_age:
                    reason = "age"
            what = "not due"
        if reason:
            what = f"rotate ({reason})"
        out.append(f"{name}: {what}")

        for archive in archives:
            archive.time = times.get(archive.old)
        if reason:
            rotated += 1
            if settings.naming == "numbered":
                key = (0,)
            else:
                day = ctx.now.astimezone(settings.offset).date()
                used = {archive.key[1] for archive in archives if archive.key[0] == day}
                counter = 1
                if used:
                    counter = 2
                    while counter in used:
                        counter += 1
                key = (day, counter)
            fresh = Archive(key, None, ctx.stamp, True, log.read_bytes())
            archives = archives + [fresh]
            if settings.naming == "numbered":
                archives.sort(key=lambda item: item.key)
                archives.remove(fresh)
                archives.insert(0, fresh)
            else:
                archives.sort(key=lambda item: item.key, reverse=True)

        keep, dropped = [], []
        for position, archive in enumerate(archives, 1):
            expired = False
            if settings.keep_days is not None and archive.time is not None:
                moment = ctx.now if archive.new else dates.parse_iso(archive.time, legacy=True)
                expired = ctx.now - moment >= timedelta(days=settings.keep_days)
            if position > settings.keep or expired:
                dropped.append(archive)
            else:
                keep.append(archive)

        for position, archive in enumerate(keep, 1):
            plain_old = archive.old
            gz = plain_old is not None and plain_old.endswith(".gz")
            will_compress = position > settings.compress_after and not gz
            if archive.new:
                will_compress = position > settings.compress_after
                gz = False
            suffix = ".gz" if gz or will_compress else ""
            if settings.naming == "numbered":
                base = f"{name}.log.{position}"
            else:
                base = f"{name}.log.{archive.key[0].isoformat()}" + (f".{archive.key[1]}" if archive.key[1] > 1 else "")
            archive.name = base + suffix
            archive.compress = will_compress
            if will_compress:
                compressed += 1
        removed += len(dropped)

        new_times = {}
        for archive in keep:
            if archive.time is not None:
                new_times[archive.name] = archive.time
            if archive.new:
                out.append(f"  new {archive.name}")
            elif archive.name != archive.old:
                out.append(f"  {archive.name} <- {archive.old}")
            else:
                out.append(f"  {archive.name}")
        for archive in dropped:
            if archive.new:
                base = f"{name}.log.{archive.key[0].isoformat()}" + (f".{archive.key[1]}" if archive.key[1] > 1 else "")
                out.append(f"  remove {base}")
            else:
                out.append(f"  remove {archive.old}")
                removals.append(archive.old)

        for archive in keep:
            if archive.new or archive.name != archive.old:
                writes.append(archive)
        for archive in keep:
            if not archive.new and archive.name != archive.old:
                removals.append(archive.old)
        if reason:
            writes.append(Archive((), None, content=b"", name=log.name))

        new_entry = {}
        if reason:
            new_entry["opened"] = ctx.stamp
        elif "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = entry.get("rotations", 0) + (1 if reason else 0)
        new_entry["archives"] = new_times
        new_entries[name] = new_entry

    out.append(f"{rotated} rotated, {removed} removed, {compressed} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    contents = {}
    for archive in writes:
        if archive.content is None:
            contents[archive.old] = (logs / archive.old).read_bytes()
    for archive in writes:
        if archive.content is not None:
            contents[id(archive)] = archive.content
    for old in removals:
        (logs / old).unlink(missing_ok=True)
    for archive in writes:
        data = archive.content if archive.content is not None else contents[archive.old]
        if archive.compress:
            data = gzip.compress(data, mtime=0)
        logs.mkdir(parents=True, exist_ok=True)
        (logs / archive.name).write_bytes(data)
    doc["streams"].update(new_entries)
    ctx.state_path.parent.mkdir(parents=True, exist_ok=True)
    state.save(ctx.state_path, doc)
    return out
EOF

